<script>
import Layout from "../../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";
import ReportsHeader from "@/components/reports-header";
import moment from 'moment';

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
    ReportsHeader,
  },
  data() {
    return {
                  day: moment(new Date(Date.now())).format("YYYY-MM-DD hh:mm:ss a"),

      totalDebtors: [],
      limit: 20,
      page: 1,
      Debtors: [],
      total: [],
      accountingPeriods: [],
      amount: 0,
      totalOneMonth: 0,
      totalTwoMonth: 0,
      totalThreeMonth: 0,
      data: {},
    };
  },
  methods: {
    getDebtors(page) {
      this.http
        .post("transactions/debits-report", {
          accounting_period_id: this.data.accounting_period_id,
          limit: this.limit,
          page,
        })
        .then((res) => {
          this.Debtors = res.data;
          this.totalOneMonth = 0;
          this.totalTwoMonth = 0;
          this.totalThreeMonth = 0;
          this.Debtors.forEach((debtor) => {
            this.totalOneMonth += parseFloat(debtor.one_month);
            this.totalTwoMonth += parseFloat(debtor.two_month);
            this.totalThreeMonth += parseFloat(debtor.three_month);
          });
        });
    },
    getAccountingPeriods() {
      this.http.get("accounting-peroids").then((resp) => {
        if (resp) {
          this.accountingPeriods = resp.data;
        }
      });
    },
  },
  created() {
    this.getDebtors(1);
    this.getAccountingPeriods();
  },
};
</script>

